USE ieee.std_logic_arith.all;
use ieee.std_logic_unsigned.all;
library work;
use work.utilities.all;
 
architecture fsm of sounding_ctrl is

   -- Architecture Declarations
   signal period_cnt: std_logic_vector(pulse_length'range);
   signal rep_cnt: std_logic_vector(pulse_repetitions'range);

   type state_type is (
      s_wait,
      s_sync,
      s_run
   );
 
   -- Declare current and next state signals
   signal current_state : state_type;
   signal next_state : state_type;

begin

   -----------------------------------------------------------------
   clocked_proc : process ( 
      clk
   )
   -----------------------------------------------------------------
   begin
      if (clk'event and clk = '1') then
         if (reset = '1') then
            current_state <= s_wait;
         else
            current_state <= next_state;

            -- Combined Actions
            case current_state is
               when s_wait => 
                  period_cnt <= (0=> '1', others => '0');
                  rep_cnt <= (others => '0');
               when s_run => 
                  if sample_en = '1' then
                     period_cnt <= period_cnt+1;
                     if period_cnt = pulse_period then
                         period_cnt <= (others => '0');
                         rep_cnt <= rep_cnt+1;
                     end if;
                  end if;
               when others =>
                  null;
            end case;
         end if;
      end if;
   end process clocked_proc;
 
   -----------------------------------------------------------------
   nextstate_proc : process ( 
      current_state,
      pulse_repetitions,
      pulse_trig,
      rep_cnt,
      sample_en
   )
   -----------------------------------------------------------------
   begin
      case current_state is
         when s_wait => 
            if (pulse_trig = '1') then 
               next_state <= s_sync;
            else
               next_state <= s_wait;
            end if;
         when s_sync => 
            if (sample_en = '1') then 
               next_state <= s_run;
            else
               next_state <= s_sync;
            end if;
         when s_run => 
            if (rep_cnt = pulse_repetitions) then 
               next_state <= s_wait;
            else
               next_state <= s_run;
            end if;
         when others =>
            next_state <= s_wait;
      end case;
   end process nextstate_proc;
 
