   output_proc : process ( 
      current_state,
      period_cnt,
      pulse_length
   )
   -----------------------------------------------------------------
   begin
      -- Default Assignment
      dds_reset <= '1';
      dma_write_enable <= '0';
      ready <= '0';

      -- Combined Actions
      case current_state is
         when s_wait => 
            ready <= '1';
         when s_run => 
            if period_cnt < pulse_length then
                dds_reset <= '0';
            end if;
            dma_write_enable <= '1';
         when others =>
            null;
      end case;
   end process output_proc;
 
